#include <stdio.h>

/* Convert a non-negative decimal integer to any base from 2 to 16
   by repeated division; the remainders are read last to first. */
void to_base(unsigned long n, int base, char *out) {
    const char *digits = "0123456789ABCDEF";
    char tmp[65];
    int i = 0, j = 0;
    if (n == 0) tmp[i++] = '0';
    while (n > 0) {
        tmp[i++] = digits[n % base];   /* remainder = next digit */
        n /= base;                     /* quotient goes on */
    }
    while (i > 0) out[j++] = tmp[--i]; /* reverse the remainders */
    out[j] = '\0';
}

int main(void) {
    unsigned long n;
    int base;
    char result[65];
    printf("Enter a decimal number and a base (2-16): ");
    if (scanf("%lu %d", &n, &base) != 2 || base < 2 || base > 16) {
        printf("Invalid input\n");
        return 1;
    }
    to_base(n, base, result);
    printf("(%lu)10 = (%s)%d\n", n, result, base);
    return 0;
}

