#include <stdio.h>

/* Print the low 8 bits of v, most significant bit first. */
void print8(int v) {
    int i;
    for (i = 7; i >= 0; i--)
        putchar(((v >> i) & 1) ? '1' : '0');
}

int main(void) {
    int a, b, sum, wrapped;
    printf("Enter two integers in -128..127: ");
    if (scanf("%d %d", &a, &b) != 2 || a < -128 || a > 127 || b < -128 || b > 127) {
        printf("Out of range\n");
        return 1;
    }
    sum = a + b;                         /* true sum */
    wrapped = (sum + 256) % 256;         /* what an 8-bit adder keeps */
    if (wrapped > 127) wrapped -= 256;   /* read it back as signed */

    printf("A   = %4d : ", a); print8(a); putchar('\n');
    printf("B   = %4d : ", b); print8(b); putchar('\n');
    printf("Sum = %4d : ", wrapped); print8(sum); putchar('\n');

    /* overflow: same-sign operands, result of the other sign */
    if ((a >= 0) == (b >= 0) && (wrapped >= 0) != (a >= 0))
        printf("Overflow: the true sum %d is outside -128..127\n", sum);
    else
        printf("No overflow\n");
    return 0;
}

