#include <stdio.h>

/* Print the low n bits of v, most significant bit first. */
void bits(unsigned v, int n) {
    int i;
    for (i = n - 1; i >= 0; i--)
        putchar(((v >> i) & 1) ? '1' : '0');
}

unsigned to_gray(unsigned b) { return b ^ (b >> 1); }

unsigned from_gray(unsigned g) {
    unsigned b = 0;
    while (g) {          /* b = g ^ g>>1 ^ g>>2 ^ ... */
        b ^= g;
        g >>= 1;
    }
    return b;
}

int main(void) {
    unsigned n, d, g;
    char s[12];
    int i, len;
    printf("Enter a decimal number (0-9999): ");
    if (scanf("%u", &n) != 1 || n > 9999) {
        printf("Invalid input\n");
        return 1;
    }
    len = sprintf(s, "%u", n);

    printf("BCD (8421): ");
    for (i = 0; i < len; i++) {
        d = s[i] - '0';
        bits(d, 4); putchar(' ');
    }
    printf("\nExcess-3  : ");
    for (i = 0; i < len; i++) {
        d = s[i] - '0';
        bits(d + 3, 4); putchar(' ');       /* each digit + 0011 */
    }
    printf("\nBinary    : "); bits(n, 14);
    g = to_gray(n);
    printf("\nGray      : "); bits(g, 14);
    printf("\nGray back : %u\n", from_gray(g));
    return 0;
}

