public class Parity {
    // even-parity bit: XOR of all data bits (1 when the count of 1s is odd)
    static int evenParityBit(int data) {
        int p = 0;
        while (data != 0) {
            p ^= (data & 1);
            data >>= 1;
        }
        return p;
    }

    static String bits(int v, int width) {
        return String.format("%" + width + "s", Integer.toBinaryString(v)).replace(' ', '0');
    }

    public static void main(String[] args) {
        char[] text = {'A', 'C', 'Z'};
        for (char ch : text) {
            int p = evenParityBit(ch);
            int frame = (p << 7) | ch;          // parity in bit 7, ASCII in bits 0-6
            System.out.printf("%c data=%s parity=%d frame=%s%n", ch,
                    bits(ch, 7), p, bits(frame, 8));
        }
        int received = 0b11000010;              // 'B' with a parity bit of 1 (wrong)
        System.out.println(evenParityBit(received) == 0 ? "OK" : "Parity error");
    }
}

